
# Example generated by Gemini when requested to generate an example
# that demonstrates how name mangling prevents name clashing and 
# thus keeps class-private members. The generated code was then verified
# and updated to use best practices and to include additional comments.

# Explanation is at the end

class TextPipeline:
    def __init__(self, data : str):
        self.data = data

    def run(self):
        # The base class safely calls its own internal helper
        cleaned = self.__clean_text()
        print(f"Pipeline output: {cleaned}")

    # A class-private method. Python mangles this to: _TextPipeline__clean_text
    def __clean_text(self) -> str:
        return self.data.strip().lower()


class SocialMediaPipeline(TextPipeline):
    # A subclass developer creates a method named '__clean_text' 
    # to handle hashtags, completely unaware the base class uses the same name.
    # Python mangles this to: _SocialMediaPipeline__clean_text
    def __clean_text(self) -> str:
        return self.data.replace("#", "[HASHTAG]")

    def run_social_metrics(self):
        # The subclass safely calls its own internal helper
        return self.__clean_text()


# --- Testing the code ---
pipeline = SocialMediaPipeline("   #Python #Coding   ")

# 1. Trigger the base class execution
# It correctly uses _TextPipeline__clean_text (stripping and lowercase)
pipeline.run()

# 2. Trigger the subclass execution
# It correctly uses _SocialMediaPipeline__clean_text (hashtag replacement)
print(f"Social metrics output: {pipeline.run_social_metrics()}")


# EXPLANATION

# If we had used a single underscore (_clean_text), Python would not 
# have mangled the name.

# Because of how inheritance works in Python, when pipeline.run() called 
# self._clean_text(), it would look up the method on the child class instance 
# first, find the SocialMediaPipeline._clean_text() implementation, and 
# execute that instead. The base class's internal cleaning logic would be 
# completely broken by the subclass.

# By using the double underscore, TextPipeline guarantees that its internal 
# routines remain isolated and reliable, no matter what a subclass developer 
# decides to name their own helper functions.